# Sector list for the Cyclical rule, per spec. Excludes Shipping and Sugar
# since neither is a distinct sector here (see module docstring).
CYCLICAL_SECTORS: set[str] = {
    "Automobile and Auto Components",
    "Metals & Mining",
    "Construction Materials",
    "Capital Goods",
    "Chemicals",
    "Realty",
}

_STRIPPED_LOOKUP: dict[str, str] = {key.strip(): value for key, value in SECTOR_MAP.items()}


def sector_of(name: str) -> str:
    """Sector for a company name, tolerant of the trailing-space quirk some
    ledger names carry ("ZF Commcercial " vs watchlist.json's "ZF Commcercial")."""
    if name in SECTOR_MAP:
        return SECTOR_MAP[name]
    return _STRIPPED_LOOKUP.get(name.strip(), "Unclassified")
